import json
import csv
import sys

def flatten_json(y, prefix=''):
    out = {}
    if isinstance(y, dict):
        for k, v in y.items():
            if isinstance(v, dict):
                out.update(flatten_json(v, prefix + k + '.'))
            elif isinstance(v, list):
                # convert list to dict with index keys
                for i, item in enumerate(v):
                    if isinstance(item, dict):
                        out.update(flatten_json(item, prefix + k + f'.{i}.'))
                    else:
                        out[prefix + k + f'.{i}'] = item
            else:
                out[prefix + k] = v
    else:
        out[prefix[:-1]] = y
    return out

def json_to_csv(json_data, csv_file):
    # Flatten each json object
    flattened = [flatten_json(item) for item in json_data]

    # Collect all keys that appear in any item
    all_keys = set()
    for item in flattened:
        all_keys.update(item.keys())
    all_keys = sorted(all_keys)

    with open(csv_file, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=all_keys)
        writer.writeheader()
        for row in flattened:
            writer.writerow(row)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} input.json output.csv")
        sys.exit(1)

    with open(sys.argv[1], 'r') as infile:
        data = json.load(infile)

    if not isinstance(data, list):
        data = [data]

    json_to_csv(data, sys.argv[2])
